export default function ({ messages, messageId, threadId }) {
  const m = messages.find((x) => x.messageId === messageId);
  if (!m || m.threadId !== threadId) throw Error("Message mismatch");
  return {
    subject: m.subject,
    sender: m.sender,
    snippet: m.snippet ?? m.preview?.body ?? "",
    now: new Date().toISOString(),
  };
}

