export default async function ({ messageId, text }, ctx) {
  if (!text.trim()) throw Error("Empty reply");
  const key = "meeting-reply:" + messageId,
    s = await ctx.state.get(key);
  if (s?.status === "pending" || s?.status === "read-pending")
    throw Error("Unknown prior Gmail outcome; inspect mailbox");
  if (s?.status === "done") return { key, skip: true, finished: true };
  if (s?.status === "reply-done") return { key, skip: true, finished: false };
  await ctx.state.set(key, { status: "pending" });
  return { key, skip: false, finished: false };
}

