export default async function ({ key, messageId }, ctx) {
  if (!messageId) throw Error("Unknown reply outcome");
  await ctx.state.set(key, { status: "reply-done", replyId: messageId });
  return { done: true };
}

n_8886b7df0bf7c65c.source:
export default async function ({ key, messageId }, ctx) {
  const s = await ctx.state.get(key);
  if (s?.status !== "reply-done") throw Error("Reply is not confirmed");
  await ctx.state.set(key, { ...s, status: "read-pending" });
  return { ids: [messageId] };
}

