export default function () {
  const now = new Date(),
    min = new Date(now.getTime() - 86400000),
    y = now.getUTCFullYear(),
    m = now.getUTCMonth() + 1,
    last = new Date(Date.UTC(y, m + 1, 0)).getUTCDate(),
    max = new Date(
      Date.UTC(
        y,
        m,
        Math.min(now.getUTCDate(), last),
        now.getUTCHours(),
        now.getUTCMinutes(),
        now.getUTCSeconds(),
        now.getUTCMilliseconds(),
      ),
    );
  return { timeMin: min.toISOString(), timeMax: max.toISOString() };
}

