export default function ({ items, token, previous }) {
  if (!Array.isArray(items)) throw Error("Invalid calendar page");
  const events = [
    ...(previous?.events ?? []),
    ...items
      .filter((e) => e.status === "confirmed" && e.start?.dateTime && e.end?.dateTime)
      .map((e) => ({ start: e.start.dateTime, end: e.end.dateTime, name: e.summary ?? "" })),
  ];
  return { state: { events }, more: !!token, token: token ?? "" };
}

